CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE categories (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, parent_id UUID REFERENCES categories(id), icon TEXT, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE connectors (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, platform VARCHAR(32) NOT NULL CHECK (platform IN ('prestashop','shopify','woocommerce','native')), config JSONB NOT NULL DEFAULT '{}', status VARCHAR(16) NOT NULL DEFAULT 'active' CHECK (status IN ('active','error','disabled')), last_sync_at TIMESTAMPTZ, sync_interval_minutes INTEGER NOT NULL DEFAULT 60, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE products (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, description TEXT, description_short TEXT, category_id UUID REFERENCES categories(id), base_price NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK(base_price >= 0), currency VARCHAR(8) NOT NULL DEFAULT 'USD', product_type VARCHAR(32) NOT NULL DEFAULT 'custom', status VARCHAR(16) NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','archived')), images JSONB NOT NULL DEFAULT '[]', metadata JSONB NOT NULL DEFAULT '{}', source_connector_id UUID REFERENCES connectors(id), external_id TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(source_connector_id, external_id));
CREATE TABLE variants (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE, name TEXT NOT NULL, sku TEXT UNIQUE, price NUMERIC(12,2), metadata JSONB NOT NULL DEFAULT '{}');
CREATE TABLE availability (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE, date DATE NOT NULL, slots_total INTEGER NOT NULL CHECK(slots_total >= 0), slots_available INTEGER NOT NULL CHECK(slots_available BETWEEN 0 AND slots_total), price_override NUMERIC(12,2) CHECK(price_override >= 0), metadata JSONB NOT NULL DEFAULT '{}', UNIQUE(product_id,date));
CREATE TABLE images (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE, url TEXT NOT NULL, alt TEXT, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), product_id UUID NOT NULL REFERENCES products(id), customer_name TEXT NOT NULL, customer_email TEXT NOT NULL, customer_phone TEXT, date_from DATE, date_to DATE, quantity INTEGER NOT NULL DEFAULT 1 CHECK(quantity > 0), total_amount NUMERIC(12,2) NOT NULL CHECK(total_amount >= 0), currency VARCHAR(8) NOT NULL DEFAULT 'USD', status VARCHAR(16) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','cancelled','completed')), payment_status VARCHAR(16) NOT NULL DEFAULT 'unpaid' CHECK(payment_status IN ('unpaid','paid','refunded')), connector_id UUID REFERENCES connectors(id), external_order_id TEXT, metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE admin_users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, totp_secret TEXT, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX products_filter_idx ON products(status, category_id, product_type); CREATE INDEX availability_product_date_idx ON availability(product_id,date); CREATE INDEX orders_created_idx ON orders(created_at);
